#include <bits/stdc++.h>using namespace std;#define int long long#define double long double void solve() {    int n, a, b;    cin >> n;    int remaining = n;    for (int i = 2; i * i <= n; i++) {        if (remaining % i == 0) {            remaining = remaining / i;            a = i;            break;        }    }    for (int i = a + 1; i * i <= remaining; i++) {        if (remaining % i == 0) {            remaining = remaining / i;            b = i;            break;        }    }    if (n % (a * b) == 0) {        int c = (n / a) / b;        if (c != 0 && c != 1 && c != a && c != b) {            cout << "YES" << "\n";            cout << a << " " << b << " " << c << "\n";            return;        }    }    cout << "NO\n";} int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int t;    cin >> t;    for (int i = 0; i < t; i++) {        solve();    }}